# Let's try to generate a random 3-regular graph and check for girth >=7. Since (3,7)-cage is McGee with 24 verts, it exists, so random may find it or a graph with girth 7.
import random
import collections

def is_valid_3_regular(edges, n=24):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    return all(len(a)==3 for a in adj)

def compute_girth(n, edges):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    def bfs(start):
        dist = [-1] * n
        dist[start] = 0
        par = [-1] * n
        q = collections.deque([start])
        min_cycle = n
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v == par[u]: continue
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    par[v] = u
                    q.append(v)
                elif dist[v] < dist[u]:  # to avoid some
                    cycle = dist[u] + dist[v] + 1
                    if cycle < min_cycle and cycle >= 3:
                        min_cycle = cycle
        return min_cycle
    return min(bfs(i) for i in range(n))

def generate_random_cubic(n=24, max_tries=10000):
    for try_num in range(max_tries):
        # Use configuration model for regular graph
        stubs = list(range(n)) * 3
        random.shuffle(stubs)
        edges = []
        used = set()
        good = True
        i = 0
        while i < len(stubs):
            u = stubs[i]
            v = stubs[i+1]
            i += 2
            if u > v:
                u, v = v, u
            if u == v or (u,v) in used:
                good = False
                break
            used.add((u,v))
        if not good or len(used) != (n*3)//2:
            continue
        edges = list(used)
        if compute_girth(n, edges) >= 7:
            return sorted(edges)
    return None

random.seed(123)  # for reproducibility
result = generate_random_cubic()
print("Found a graph:", result is not None)
if result:
    print("Example edges:", result[:10], "...")
    print("Total edges:", len(result))
